/**
 * Voices: one model for every voice VideoDubber can speak with.
 *
 * Three kinds of voice reach the same pickers:
 *   - **presets** that ship with a TTS engine (VieNeu's 25, Kokoro's 54…) or
 *     download one by one (Piper's 183 models, 2,700 speakers);
 *   - **voice profiles** the user makes from a recording or a file (cloning);
 *   - **project voices**, profiles made from a project's own source video,
 *     which live and die with that project.
 *
 * The catalog of presets is a reviewed snapshot inside the app (generated by
 * scripts/gen-voice-catalog.mjs at pinned upstream revisions, every file with a
 * sha256); only voices, engines and previews download, on demand. See
 * docs/VOICES.md.
 */
import type { LanguageCode } from './domain.js';

/** The engine family that speaks a voice. */
export type VoiceEngineId =
  /** Piper (bundled): 183 downloadable models in 53 languages. */
  | 'piper'
  /** VieNeu v3-Turbo SDK 3.0.5: the ten voices VideoDubber shipped first. */
  | 'vieneu-classic'
  /** VieNeu v3-Turbo SDK 3.8: 25 Vietnamese voices and voice cloning. */
  | 'vieneu'
  /** ZeroTTS: 8 Vietnamese voices (ONNX). */
  | 'zerotts'
  /** Kokoro-82M: 54 voices in 9 locales (no Vietnamese). */
  | 'kokoro'
  /** Supertonic 3: 10 voices, each in 31 languages. */
  | 'supertonic'
  /** VoxCPM2 (audio.cpp): cross-lingual voice cloning on a GPU / Apple chip. */
  | 'voxcpm'
  /** OpenAI TTS (cloud, opt-in with a key). */
  | 'openai';

/**
 * How freely a voice may be used, for its badge and the licence filter. The
 * label carries the exact licence; the category only colours it.
 */
export type VoiceLicenseCategory =
  /** CC0, public domain, MIT, Apache-2.0, BSD. */
  | 'permissive'
  /** CC BY / CC BY-SA: free to use with credit (and share-alike). */
  | 'attribution'
  /** Commercial use allowed, listed uses forbidden (OpenRAIL-M). */
  | 'use-restricted'
  /** CC BY-NC and research-only data. */
  | 'non-commercial'
  /** A cloud service's own terms (OpenAI). */
  | 'service-terms'
  /** Not stated upstream, or not yet reviewed. */
  | 'unknown';

export interface VoiceLicense {
  category: VoiceLicenseCategory;
  /** Short label for the badge, e.g. "Apache-2.0", "CC BY-NC-SA 4.0". */
  label: string;
  /** Where the licence was read (a model card, a LICENSE file). */
  sourceUrl?: string;
  /** Credit line the licence asks for, when any. */
  attribution?: string;
}

/** One file a voice or engine needs, pinned to an upstream commit. */
export interface VoiceFile {
  /** A commit-pinned URL, never a branch. */
  url: string;
  sha256: string;
  bytes: number;
  /** Where it lands, relative to the engine's voice folder. */
  destPath: string;
}

/** A playable sample that needs nothing installed. */
export interface VoicePreview {
  url: string;
  sha256: string;
  bytes: number;
  /** What it says, when known. */
  text?: string;
}

/** A speaker inside a multi-speaker model (Piper). */
export interface VoiceSpeaker {
  index: number;
  /** The upstream speaker name, e.g. "p225" or "0". */
  name: string;
}

/** Vietnamese regional accent, for the filter and the label. */
export type VoiceAccent = 'north' | 'central' | 'south';

/** One preset voice in the catalog. */
export interface VoiceEntry {
  /**
   * Globally unique voice id, the value stored in project settings. Piper ids
   * are upstream names ("vi_VN-vais1000-medium"; a chosen speaker of a
   * multi-speaker model is "<id>#<index>"), the others carry an engine prefix
   * ("vieneu38-hai-dang", "kokoro-af_heart"). Existing ids never change.
   */
  id: string;
  engine: VoiceEngineId;
  /** The voice's own name ("Hải Đăng", "Heart"). */
  name: string;
  /** Languages it speaks (BCP-47); ["*"] = every language its engine speaks. */
  languages: LanguageCode[];
  gender?: 'female' | 'male';
  accent?: VoiceAccent;
  /** Upstream descriptors: age, style ("news", "warm"…). */
  tags?: string[];
  /** Output sample rate in Hz. */
  sampleRate: number;
  /** Piper quality tier. */
  quality?: 'x_low' | 'low' | 'medium' | 'high';
  /** Multi-speaker models list their speakers; pick one with "<id>#<index>". */
  speakers?: VoiceSpeaker[];
  license: VoiceLicense;
  /** Files to download for this voice; empty when the engine ships it. */
  files: VoiceFile[];
  /** Download size of `files` (MB); 0 when the engine ships the voice. */
  sizeMb: number;
  preview?: VoicePreview;
  /** The engine maker's or our own pick for its language. */
  recommended?: boolean;
  /** A newer engine release dropped it; this voice is the suggested stand-in. */
  replacedBy?: string;
}

/** What one engine needs and can do. */
export interface VoiceEngineInfo {
  id: VoiceEngineId;
  /** The TTS provider id that speaks its voices. */
  providerId: string;
  /** Engine packs that provide it, best first (any one is enough); [] = built in. */
  packIds: string[];
  /** Languages (BCP-47 base subtags) it speaks. */
  languages: string[];
  /** Can make a voice from a short recording. */
  cloning: boolean;
  /** Can clone from speech in another language than it speaks the line in. */
  crossLingual: boolean;
  /** Honors a speaking rate natively (else the time-stretcher fits lines). */
  speedControl: boolean;
  sampleRate: number;
  /** For cloning engines: what a reference recording should be. */
  reference?: VoiceReferencePolicy;
  /** The engine's own model licence (each voice carries its own too). */
  license: VoiceLicense;
  /** Needs an NVIDIA GPU, an Apple chip, or neither (CPU everywhere). */
  hardware: 'any' | 'gpu-recommended';
  /** Upstream maintenance has ended (Supertonic). */
  archived?: boolean;
}

/** How much of a reference recording a cloning engine uses, and how. */
export interface VoiceReferencePolicy {
  /** Below this much speech the recording is refused. */
  minSpeechMs: number;
  /** What to aim for. */
  idealMs: number;
  /** The engine uses at most this much. */
  maxMs: number;
  /** Whether it reads the reference's transcript. */
  transcript: 'unused' | 'optional' | 'required';
}

/** The user's statement that they may clone a voice, stored with it. */
export interface VoiceConsent {
  /** Version of the statement text (a new version asks again). */
  statementVersion: string;
  /** The literal text the user agreed to, in the language it was shown in. */
  statementText: string;
  acceptedAt: string;
  /** Whose voice: the user's own, someone who allowed it, or a source video's. */
  relation: 'self' | 'authorized' | 'source-video';
  /** A declaration is the user's commitment, not identity verification. */
  method: 'declaration';
}

/** What the checks found in a reference recording. */
export interface VoiceReferenceChecks {
  /** Speech inside the chosen window (ms). */
  speechMs: number;
  /** Average level of the speech before levelling (dBFS, RMS). */
  levelDb?: number;
  /** Share of samples at full scale (0..1). */
  clippedShare?: number;
  /** Speech level against the background between words (dB; higher is cleaner). */
  snrDb?: number;
  /** Longest pause inside the window (ms). */
  longestPauseMs?: number;
  /**
   * Findings, as keys under `voice-check.*`: "too-short" refuses the
   * recording; the others ("short", "too-quiet", "clipped", "noisy",
   * "long-pause") warn and the user decides.
   */
  warnings: VoiceCheckWarning[];
}

export type VoiceCheckWarning = 'too-short' | 'short' | 'too-quiet' | 'clipped' | 'noisy' | 'long-pause';

/** Engine-specific voice data made from a reference (enrollment). */
export interface VoiceEnrollment {
  /** File with the engine's voice data, relative to the profile folder. */
  file: string;
  /**
   * Hash of that data: identifies the voice in clip caches and seeds, so a
   * rename keeps every finished clip and a re-recording redoes them.
   */
  fingerprint: string;
  engineVersion: string;
  createdAt: string;
}

/** A voice the user made. The recording is the source; enrollments derive. */
export interface VoiceProfile {
  /** "vp_" + random; stored in project settings like a preset id. */
  id: string;
  name: string;
  createdAt: string;
  updatedAt: string;
  /** In the library, or private to one project (made from its source video). */
  scope: { kind: 'library' } | { kind: 'project'; projectId: string; speakerId?: string };
  /** The engine that speaks it by default. */
  engine: VoiceEngineId;
  source: { kind: 'recording' | 'file' | 'project-lines' | 'project-speaker'; fileName?: string; segmentIds?: string[] };
  /** Language spoken in the reference, when detected. */
  referenceLanguage?: string;
  /** The cleaned reference clip; absent when the user kept only the voice data. */
  reference?: {
    file: string;
    durationMs: number;
    sampleRate: number;
    sha256: string;
    transcript?: string;
    transcriptBy?: 'stt' | 'user' | 'script';
  };
  checks: VoiceReferenceChecks;
  consent: VoiceConsent;
  /** Per engine: the voice data made from the reference. */
  enrollments: Partial<Record<VoiceEngineId, VoiceEnrollment>>;
  /** Free-form note. */
  note?: string;
  /**
   * Whose voice it is, for casting speakers by gender (cast_voices). Never
   * taken from pitch, never set silently: the user's clones overlap (a male
   * clone at 194 Hz sits above a female one at 174 Hz, claude-dubber
   * 2026-11-21). A suggestion comes from comparing its voice print with
   * built-in voices whose gender is known; the user confirms it. Profiles made
   * before this have none: unconfirmed, and casting asks about them.
   */
  gender?: VoiceProfileGender;
  /**
   * Kept for one main character: casting gives it to one main speaker at
   * most, never to the minor speakers' shared voices and never as the voice
   * of every speaker of a gender who has none (voices/mainOnly.ts). The user's
   * own clone is the case (claude-dubber, 2026-11-25).
   */
  mainOnly?: boolean;
  /** Its voice print and pitch, measured on its preview (speaker detection's embedding model). */
  voicePrint?: { print: number[]; f0Hz?: number; model?: string };
}

/** A cloned voice's gender: the user's word (`confirmed`), or a suggestion waiting for it. */
export interface VoiceProfileGender {
  value: 'female' | 'male';
  confirmed: boolean;
  /** How sure the suggestion was (0..1), when it came from voice prints. */
  confidence?: number;
}

/** A row of the voice library: a preset, or a profile, with its state here. */
export interface VoiceLibraryItem {
  kind: 'preset' | 'profile';
  id: string;
  engine: VoiceEngineId;
  name: string;
  languages: LanguageCode[];
  gender?: 'female' | 'male';
  accent?: VoiceAccent;
  tags?: string[];
  quality?: VoiceEntry['quality'];
  speakers?: VoiceSpeaker[];
  license: VoiceLicense;
  sizeMb: number;
  /** A preview can be played (a sample exists, or the voice is installed). */
  hasPreview: boolean;
  /** The catalog has a sample of it (playable before installing). */
  sample?: boolean;
  recommended?: boolean;
  replacedBy?: string;
  /** The voice itself is on this computer (files, or shipped by its engine). */
  installed: boolean;
  /** Its engine is installed and runs here. */
  engineInstalled: boolean;
  /** Its engine can run on this computer at all. */
  engineAvailable: boolean;
  favorite: boolean;
  /** Profiles: library or project, and which project. */
  scope?: VoiceProfile['scope'];
  /** Profiles: the gender is the user's word (false: a suggestion, or not set). */
  genderConfirmed?: boolean;
  /** Profiles: kept for one main character (VoiceProfile.mainOnly). */
  mainOnly?: boolean;
}

/** GET /voices. */
export interface VoiceLibraryResponse {
  voices: VoiceLibraryItem[];
  /** Matches before paging. */
  total: number;
  engines: VoiceEngineInfo[];
}

/** POST /voices/:id/install. */
export interface VoiceInstallResult {
  started: boolean;
  /** Engine packs installed along with the voice (by id). */
  enginePacks: string[];
  /** Total download (MB) this starts. */
  downloadMb: number;
}

/** Recognise a profile id. */
export function isVoiceProfileId(voiceId: string | undefined | null): boolean {
  return typeof voiceId === 'string' && voiceId.startsWith('vp_');
}

/**
 * The engine of a preset voice id, from its prefix (offline, no catalog).
 * Profiles ("vp_…") return undefined: their engine is in the profile.
 */
export function voiceEngineOfId(voiceId: string | undefined | null): VoiceEngineId | undefined {
  if (!voiceId) return undefined;
  if (isVoiceProfileId(voiceId)) return undefined;
  if (voiceId.startsWith('vieneu-v3-') || voiceId.startsWith('vieneu-v2-')) return 'vieneu-classic';
  if (voiceId.startsWith('vieneu38-')) return 'vieneu';
  if (voiceId.startsWith('zerotts-')) return 'zerotts';
  if (voiceId.startsWith('kokoro-')) return 'kokoro';
  if (voiceId.startsWith('supertonic-')) return 'supertonic';
  if (voiceId.startsWith('voxcpm-')) return 'voxcpm';
  if (voiceId.startsWith('openai-')) return 'openai';
  return 'piper';
}

/** Split a Piper "<model>#<speaker>" id. */
export function splitSpeakerVoiceId(voiceId: string): { modelId: string; speaker?: number } {
  const at = voiceId.lastIndexOf('#');
  if (at <= 0) return { modelId: voiceId };
  const speaker = Number(voiceId.slice(at + 1));
  return Number.isInteger(speaker) && speaker >= 0 ? { modelId: voiceId.slice(0, at), speaker } : { modelId: voiceId };
}

/** The TTS provider id of each engine. */
export const VOICE_ENGINE_PROVIDER: Readonly<Record<VoiceEngineId, string>> = {
  piper: 'piper-local',
  'vieneu-classic': 'neural-tts',
  vieneu: 'vieneu-tts',
  zerotts: 'zerotts',
  kokoro: 'kokoro',
  supertonic: 'supertonic',
  voxcpm: 'voxcpm',
  openai: 'openai-tts',
};

/** The engine of a TTS provider id, if it is one of the voice engines. */
export function voiceEngineOfProvider(providerId: string | undefined): VoiceEngineId | undefined {
  if (!providerId) return undefined;
  const hit = (Object.entries(VOICE_ENGINE_PROVIDER) as [VoiceEngineId, string][]).find(([, p]) => p === providerId);
  return hit?.[0];
}
